import { state, getCurrentMission } from './state';
import { COLORS, getLandColor, getSandColor } from '@/shared/constants';

const canvas = document.getElementById('editorCanvas') as HTMLCanvasElement;
const ctx = canvas.getContext('2d')!;

export const drawMap = () => {
    const m = getCurrentMission();
    if (!m) return;

    ctx.clearRect(0, 0, 600, 600);
    const tSize = (600 / m.gridSize) * state.zoom;

    const pUI = document.getElementById('ui_pad') as HTMLElement;
    const cUI = document.getElementById('ui_carrier') as HTMLElement;
    const bUI = document.getElementById('ui_boat') as HTMLElement;
    const sUI = document.getElementById('ui_submarine') as HTMLElement;
    const wUI = document.getElementById('ui_wind') as HTMLElement;
    const wtUI = document.getElementById('ui_wt') as HTMLElement;
    const pwUI = document.getElementById('ui_plane_wreck') as HTMLElement;
    const sbUI = document.getElementById('ui_sailboat_broken') as HTMLElement;
    const owUI = document.getElementById('ui_ornithopter_wreck') as HTMLElement;
    const bwcUI = document.getElementById('ui_baywatch_car') as HTMLElement;
    const bwhUI = document.getElementById('ui_baywatch_hq') as HTMLElement;
    const bwtUI2 = document.getElementById('ui_baywatch_tower') as HTMLElement;
    const csUI = document.getElementById('ui_concert_stage') as HTMLElement;
    const ftUI = document.getElementById('ui_festival_tent') as HTMLElement;
    const ftbUI = document.getElementById('ui_festival_tent_broken') as HTMLElement;
    const fcUI = document.getElementById('ui_festival_car') as HTMLElement;
    const xhUI = document.getElementById('ui_xmas_house') as HTMLElement;
    const xlUI = document.getElementById('ui_xmas_lantern') as HTMLElement;
    const slUI = document.getElementById('ui_sleigh') as HTMLElement;
    const rdUI = document.getElementById('ui_reindeer') as HTMLElement;

    if (pUI) pUI.style.display = 'none';
    if (cUI) cUI.style.display = 'none';
    if (bUI) bUI.style.display = 'none';
    if (sUI) sUI.style.display = 'none';
    if (wtUI) wtUI.style.display = 'none';
    if (wUI) wUI.style.display = 'none';
    if (pwUI) pwUI.style.display = 'none';
    if (sbUI) sbUI.style.display = 'none';
    if (owUI) owUI.style.display = 'none';
    if (bwcUI) bwcUI.style.display = 'none';
    if (bwhUI) bwhUI.style.display = 'none';
    if (bwtUI2) bwtUI2.style.display = 'none';
    if (csUI) csUI.style.display = 'none';
    if (ftUI) ftUI.style.display = 'none';
    if (ftbUI) ftbUI.style.display = 'none';
    if (fcUI) fcUI.style.display = 'none';
    if (xhUI) xhUI.style.display = 'none';
    if (xlUI) xlUI.style.display = 'none';
    if (slUI) slUI.style.display = 'none';
    if (rdUI) rdUI.style.display = 'none';

    // ── Terrain ────────────────────────────────────────────────────────────────
    const wl: number = (m as any).waterLevel ?? 0;
    const isSnow: boolean = !!(m as any).snow;
    for (let x = Math.floor(state.panX); x < Math.min(m.gridSize, state.panX + 600 / tSize + 1); x++) {
        for (let y = Math.floor(state.panY); y < Math.min(m.gridSize, state.panY + 600 / tSize + 1); y++) {
            const h = m.terrain[x][y];
            const isSand = h > wl && ((m as any).sand?.[x]?.[y] ?? 0) > 0;
            const isPavement = h > wl && ((m as any).pavement?.[x]?.[y] ?? 0) > 0;
            const landColor = isSnow ? `rgb(${190 + Math.floor(h * 8)},${205 + Math.floor(h * 7)},${220 + Math.floor(h * 6)})` : getLandColor(h, false);
            const waterColor = isSnow ? '#0a3060' : COLORS.water;
            ctx.fillStyle = h <= wl ? waterColor : isPavement ? '#808088' : isSand ? getSandColor(h) : landColor;
            ctx.fillRect((x - state.panX) * tSize, (y - state.panY) * tSize, tSize + 1.5, tSize + 1.5);
        }
    }

    // ── Objects ────────────────────────────────────────────────────────────────
    m.objects.forEach((obj, idx) => {
        const isSelected = state.selectedObjectIdx === idx;
        const ox = (obj.x - state.panX) * tSize;
        const oy = (obj.y - state.panY) * tSize;

        if (obj.type === 'pad') {
            if (isSelected) {
                ctx.shadowBlur = 10;
                ctx.shadowColor = COLORS.padStroke;
            }
            ctx.fillStyle = COLORS.padFill;
            ctx.fillRect(ox, oy, 7 * tSize, 7 * tSize);
            ctx.strokeStyle = COLORS.padStroke;
            ctx.strokeRect(ox, oy, 7 * tSize, 7 * tSize);
            ctx.fillStyle = COLORS.textLight;
            ctx.beginPath();
            ctx.arc(ox + 3.5 * tSize, oy + 3.5 * tSize, Math.max(4, tSize / 2), 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;
            if (m.spawnObject === 'pad') {
                ctx.fillStyle = COLORS.uiHighlight;
                ctx.font = 'bold 12px monospace';
                ctx.fillText('START', ox, oy - 5);
            }
            if (isSelected && pUI) {
                pUI.style.display = 'block';
                pUI.style.left = Math.min(600 - 150, Math.max(0, ox + 8 * tSize + 10)) + 'px';
                pUI.style.top = Math.min(600 - 100, Math.max(0, oy)) + 'px';
                const btn = document.getElementById('btn_spawn_pad');
                if (btn) btn.style.background = m.spawnObject === 'pad' ? COLORS.uiHighlight : 'var(--accent)';
            }
        } else if (obj.type === 'carrier' || obj.type === 'boat' || obj.type === 'pilot_boat' || obj.type === 'sar_boat' || obj.type === 'salvage_tug' || obj.type === 'supply_vessel' || obj.type === 'frigate') {
            const isCarrier = obj.type === 'carrier';
            const rad = (obj.angle * Math.PI) / 180;

            // Path line / ellipse
            ctx.save();
            ctx.setLineDash([5, 5]);
            ctx.strokeStyle = isCarrier ? COLORS.carrierPath : '#4af';
            if (obj.path === 'straight') {
                ctx.beginPath();
                ctx.moveTo(ox, oy);
                ctx.lineTo(ox + Math.cos(rad) * 1000, oy + Math.sin(rad) * 1000);
                ctx.stroke();
            } else if (obj.path === 'circle') {
                const rX = obj.radius * tSize;
                const rY = rX * 0.8;
                const t0 = Math.atan2(-Math.cos(rad) / rX, Math.sin(rad) / rY);
                const centerGridX = obj.x - Math.cos(t0) * obj.radius;
                const centerGridY = obj.y - Math.sin(t0) * obj.radius * 0.8;
                const c_px = (centerGridX - state.panX) * tSize;
                const c_py = (centerGridY - state.panY) * tSize;
                ctx.beginPath();
                ctx.ellipse(c_px, c_py, rX, rY, 0, 0, Math.PI * 2);
                ctx.stroke();
                ctx.fillStyle = isCarrier ? COLORS.carrierPath : '#4af';
                ctx.fillRect(c_px - 3, c_py - 3, 6, 6);
            }
            ctx.restore();

            // Ship body
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            if (isSelected) {
                ctx.shadowBlur = 10;
                ctx.shadowColor = COLORS.textLight;
            }

            if (isCarrier) {
                ctx.fillStyle = COLORS.carrierBase;
                ctx.fillRect(-8 * tSize, -3.5 * tSize, 16 * tSize, 7 * tSize);
                ctx.fillStyle = COLORS.carrierAccent;
                ctx.beginPath();
                ctx.moveTo(8 * tSize, 0);
                ctx.lineTo(5 * tSize, -3.5 * tSize);
                ctx.lineTo(5 * tSize, 3.5 * tSize);
                ctx.fill();
            } else if (obj.type === 'pilot_boat') {
                // hull: -1.61..1.75 × ±0.7 (×0.7 scale)
                ctx.fillStyle = '#ffcc00';
                ctx.fillRect(-1.61 * tSize, -0.7 * tSize, 2.32 * tSize, 1.4 * tSize);
                ctx.fillStyle = '#eebb00';
                ctx.beginPath();
                ctx.moveTo(0.71 * tSize, -0.7 * tSize);
                ctx.lineTo(1.75 * tSize, 0);
                ctx.lineTo(0.71 * tSize, 0.7 * tSize);
                ctx.fill();
                ctx.fillStyle = '#444';
                ctx.fillRect(-0.56 * tSize, -0.42 * tSize, 0.84 * tSize, 0.84 * tSize);
            } else if (obj.type === 'sar_boat') {
                // hull: -1.61..1.75 × ±0.7 (×0.7 scale)
                ctx.fillStyle = '#d32f2f';
                ctx.fillRect(-1.61 * tSize, -0.7 * tSize, 2.32 * tSize, 1.4 * tSize);
                ctx.fillStyle = '#b71c1c';
                ctx.beginPath();
                ctx.moveTo(0.71 * tSize, -0.7 * tSize);
                ctx.lineTo(1.75 * tSize, 0);
                ctx.lineTo(0.71 * tSize, 0.7 * tSize);
                ctx.fill();
                ctx.fillStyle = '#e6e6e6';
                ctx.fillRect(-0.56 * tSize, -0.28 * tSize, 0.91 * tSize, 0.56 * tSize);
            } else if (obj.type === 'salvage_tug') {
                // hull: -2.5..3.2 × ±1.2; superstructure: 1.0..2.2 × ±0.8
                ctx.fillStyle = '#888';
                ctx.fillRect(-2.5 * tSize, -1.2 * tSize, 5.7 * tSize, 2.4 * tSize);
                ctx.fillStyle = '#aaa';
                ctx.beginPath();
                ctx.moveTo(3.2 * tSize, -1.2 * tSize);
                ctx.lineTo(3.8 * tSize, 0);
                ctx.lineTo(3.2 * tSize, 1.2 * tSize);
                ctx.fill();
                ctx.fillStyle = '#eee';
                ctx.fillRect(1.0 * tSize, -0.8 * tSize, 1.2 * tSize, 1.6 * tSize);
            } else if (obj.type === 'supply_vessel') {
                // hull: -3.5..3.4 × ±1.2; yellow cab: 0.2..2.5 × ±0.9
                ctx.fillStyle = '#0d233a';
                ctx.fillRect(-3.5 * tSize, -1.2 * tSize, 6.9 * tSize, 2.4 * tSize);
                ctx.fillStyle = '#1a3050';
                ctx.beginPath();
                ctx.moveTo(3.2 * tSize, -1.2 * tSize);
                ctx.lineTo(3.8 * tSize, 0);
                ctx.lineTo(3.2 * tSize, 1.2 * tSize);
                ctx.fill();
                ctx.fillStyle = '#ffcd07';
                ctx.fillRect(0.2 * tSize, -0.9 * tSize, 2.3 * tSize, 1.8 * tSize);
            } else if (obj.type === 'frigate') {
                // Fregatte: 12 × 3.6, Aufbau mittschiffs, Helipad achtern
                ctx.fillStyle = '#5a6673';
                ctx.fillRect(-6 * tSize, -1.8 * tSize, 12 * tSize, 3.6 * tSize);
                ctx.fillStyle = '#7a8899';
                ctx.beginPath();
                ctx.moveTo(6 * tSize, 0);
                ctx.lineTo(4 * tSize, -1.8 * tSize);
                ctx.lineTo(4 * tSize, 1.8 * tSize);
                ctx.fill();
                // Aufbau
                ctx.fillStyle = '#8899aa';
                ctx.fillRect(0.3 * tSize, -1.4 * tSize, 2.5 * tSize, 2.8 * tSize);
                // Helipad-Markierung
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = Math.max(1, tSize * 0.15);
                ctx.strokeRect(-5.0 * tSize, -1.0 * tSize, 2.5 * tSize, 2.0 * tSize);
            } else {
                // Sailboat: schlanker Rumpf
                ctx.fillStyle = '#ddd';
                ctx.beginPath();
                ctx.moveTo(5 * tSize, 0);
                ctx.lineTo(-4 * tSize, -2 * tSize);
                ctx.lineTo(-4 * tSize, 2 * tSize);
                ctx.closePath();
                ctx.fill();
                ctx.fillStyle = '#fff';
                ctx.fillRect(-4 * tSize, -0.3 * tSize, 9 * tSize, 0.6 * tSize);
                // Mast
                ctx.strokeStyle = '#bbb';
                ctx.lineWidth = Math.max(1, tSize * 0.3);
                ctx.beginPath();
                ctx.moveTo(0, 0);
                ctx.lineTo(0, -6 * tSize);
                ctx.stroke();
            }
            ctx.shadowBlur = 0;

            ctx.translate(0, 0);
            ctx.rotate(-rad);
            ctx.fillStyle = COLORS.textDark;
            ctx.font = 'bold 11px monospace';
            ctx.fillText(obj.speed + 'kn', -15, 4);
            if (m.spawnObject === obj.type) {
                ctx.fillStyle = COLORS.uiHighlight;
                ctx.fillText('START', -15, -15);
            }
            ctx.restore();

            // Floating UI panel
            if (isSelected) {
                const panel = isCarrier ? cUI : bUI;
                if (panel) {
                    panel.style.display = 'block';
                    panel.style.left = Math.min(600 - 180, Math.max(0, ox + 20)) + 'px';
                    panel.style.top = Math.min(600 - 200, Math.max(0, oy + 20)) + 'px';
                    // sync form fields
                    syncVesselUI(obj, isCarrier ? 'carrier' : 'boat');
                    if (isCarrier) {
                        const btn = document.getElementById('btn_spawn_carrier');
                        if (btn)
                            btn.style.background = m.spawnObject === 'carrier' ? COLORS.uiHighlight : 'var(--accent)';
                    }
                }
            }
        } else if (obj.type === 'submarine') {
            const rad = (obj.angle * Math.PI) / 180;
            ctx.save();
            ctx.setLineDash([4, 4]);
            ctx.strokeStyle = '#666';
            if (obj.path === 'straight') {
                ctx.beginPath();
                ctx.moveTo(ox, oy);
                ctx.lineTo(ox + Math.cos(rad) * 1000, oy + Math.sin(rad) * 1000);
                ctx.stroke();
            } else if (obj.path === 'circle') {
                const rX = obj.radius * tSize, rY = rX * 0.8;
                const t0 = Math.atan2(-Math.cos(rad) / rX, Math.sin(rad) / rY);
                const c_px = ((obj.x - Math.cos(t0) * obj.radius) - state.panX) * tSize;
                const c_py = ((obj.y - Math.sin(t0) * obj.radius * 0.8) - state.panY) * tSize;
                ctx.beginPath(); ctx.ellipse(c_px, c_py, rX, rY, 0, 0, Math.PI * 2); ctx.stroke();
            }
            ctx.restore();
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#aaa'; }
            // Hull
            ctx.fillStyle = '#111';
            ctx.beginPath();
            ctx.moveTo(6 * tSize, 0);
            ctx.lineTo(4 * tSize, -1.2 * tSize);
            ctx.lineTo(-5 * tSize, -1.2 * tSize);
            ctx.lineTo(-5.5 * tSize, 0);
            ctx.lineTo(-5 * tSize, 1.2 * tSize);
            ctx.lineTo(4 * tSize, 1.2 * tSize);
            ctx.closePath();
            ctx.fill();
            // Conning tower
            ctx.fillStyle = '#222';
            ctx.fillRect(0.5 * tSize, -0.5 * tSize, 1.8 * tSize, 1 * tSize);
            ctx.shadowBlur = 0;
            ctx.rotate(-rad);
            ctx.fillStyle = '#999';
            ctx.font = 'bold 11px monospace';
            ctx.fillText(obj.speed + 'kn', -15, 4);
            ctx.restore();
            if (isSelected && sUI) {
                sUI.style.display = 'block';
                sUI.style.left = Math.min(600 - 180, Math.max(0, ox + 20)) + 'px';
                sUI.style.top = Math.min(600 - 150, Math.max(0, oy + 20)) + 'px';
                syncVesselUI(obj, 'submarine');
            }
        } else if (obj.type === 'lighthouse') {
            const lx = (obj.x + 0.5 - state.panX) * tSize;
            const ly = (obj.y + 0.5 - state.panY) * tSize;
            ctx.fillStyle = COLORS.lighthouseBase;
            ctx.beginPath();
            ctx.arc(lx, ly, tSize * 0.8, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = COLORS.lighthouseLight;
            ctx.beginPath();
            ctx.arc(lx, ly, tSize * 0.4, 0, Math.PI * 2);
            ctx.fill();
        } else if (obj.type === 'research_platform') {
            const rx = (obj.x - state.panX) * tSize;
            const ry = (obj.y - state.panY) * tSize;
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#4af'; }
            // Pylon
            ctx.fillStyle = '#ffcc00';
            ctx.fillRect(rx - 0.4 * tSize, ry - 0.4 * tSize, 0.8 * tSize, 0.8 * tSize);
            // Main deck
            ctx.fillStyle = '#666';
            ctx.fillRect(rx - 1.5 * tSize, ry - 1.5 * tSize, 3 * tSize, 3 * tSize);
            // Helideck (offset to the left: x=-3.5..-1.5)
            ctx.fillStyle = '#2a8f2a';
            ctx.fillRect(rx - 3.5 * tSize, ry - 1.2 * tSize, 2 * tSize, 2.4 * tSize);
            // H marker on helideck
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = Math.max(1, tSize * 0.2);
            ctx.beginPath();
            ctx.moveTo(rx - 3.1 * tSize, ry - 0.7 * tSize);
            ctx.lineTo(rx - 3.1 * tSize, ry + 0.7 * tSize);
            ctx.moveTo(rx - 2.4 * tSize, ry - 0.7 * tSize);
            ctx.lineTo(rx - 2.4 * tSize, ry + 0.7 * tSize);
            ctx.moveTo(rx - 3.1 * tSize, ry);
            ctx.lineTo(rx - 2.4 * tSize, ry);
            ctx.stroke();
            ctx.shadowBlur = 0;
        } else if (obj.type === 'wind_turbine') {
            const wx = (obj.x + 0.5 - state.panX) * tSize;
            const wy = (obj.y + 0.5 - state.panY) * tSize;
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#4f4'; }
            // Pole
            ctx.fillStyle = '#ccc';
            ctx.beginPath();
            ctx.arc(wx, wy, tSize * 0.25, 0, Math.PI * 2);
            ctx.fill();
            // Blades (3)
            ctx.strokeStyle = '#eee';
            ctx.lineWidth = Math.max(1, tSize * 0.15);
            for (let i = 0; i < 3; i++) {
                const a = (i / 3) * Math.PI * 2;
                ctx.beginPath();
                ctx.moveTo(wx, wy);
                ctx.lineTo(wx + Math.cos(a) * 3 * tSize, wy + Math.sin(a) * 3 * tSize);
                ctx.stroke();
            }
            // Beacon light (static preview)
            ctx.fillStyle = '#ff2200';
            ctx.beginPath();
            ctx.arc(wx, wy - tSize * 0.35, Math.max(2, tSize * 0.18), 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;
            if (isSelected && wtUI) {
                wtUI.style.display = 'block';
                wtUI.style.left = Math.min(600 - 140, Math.max(0, wx + 20)) + 'px';
                wtUI.style.top = Math.min(600 - 60, Math.max(0, wy + 20)) + 'px';
                const spinEl = document.getElementById('m_wt_spinning') as HTMLInputElement;
                if (spinEl) spinEl.checked = !!(obj as any).spinning;
            }
        } else if ((obj as any).type === 'plane_wreck') {
            const pw = obj as any;
            const ox = (pw.x + 0.5 - state.panX) * tSize;
            const oy = (pw.y + 0.5 - state.panY) * tSize;
            const rad = ((pw.angle ?? 0) * Math.PI) / 180;
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#fa0'; }
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            // Scorch mark
            ctx.fillStyle = '#1a1612';
            ctx.beginPath();
            ctx.ellipse(0.3 * tSize, 0, 1.2 * tSize, 0.7 * tSize, 0, 0, Math.PI * 2);
            ctx.fill();
            // Fuselage
            ctx.fillStyle = '#d4c022';
            ctx.fillRect(-1.5 * tSize, -0.15 * tSize, 2.8 * tSize, 0.3 * tSize);
            // Wings (high-wing cross)
            ctx.fillRect(-0.4 * tSize, -1.2 * tSize, 0.35 * tSize, 2.4 * tSize);
            // Tail fin
            ctx.fillStyle = '#cc1e00';
            ctx.fillRect(-1.5 * tSize, -0.35 * tSize, 0.5 * tSize, 0.7 * tSize);
            ctx.restore();
            ctx.shadowBlur = 0;
            if (isSelected && pwUI) {
                pwUI.style.display = 'block';
                pwUI.style.left = Math.min(600 - 130, Math.max(0, ox + 20)) + 'px';
                pwUI.style.top = Math.min(600 - 60, Math.max(0, oy)) + 'px';
                const angleEl = document.getElementById('m_pw_angle') as HTMLInputElement;
                if (angleEl) angleEl.value = (pw.angle ?? 0).toString();
            }
        } else if ((obj as any).type === 'sailboat_broken') {
            const sb = obj as any;
            const ox = (sb.x + 0.5 - state.panX) * tSize;
            const oy = (sb.y + 0.5 - state.panY) * tSize;
            const rad = ((sb.angle ?? 0) * Math.PI) / 180;
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#fa0'; }
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            // Hull
            ctx.fillStyle = '#933';
            ctx.beginPath();
            ctx.moveTo( 1.2 * tSize,  0);
            ctx.lineTo( 0.2 * tSize, -0.45 * tSize);
            ctx.lineTo(-1.0 * tSize, -0.35 * tSize);
            ctx.lineTo(-1.0 * tSize,  0.35 * tSize);
            ctx.lineTo( 0.2 * tSize,  0.45 * tSize);
            ctx.closePath();
            ctx.fill();
            // Deck
            ctx.fillStyle = '#a85';
            ctx.fillRect(-0.9 * tSize, -0.3 * tSize, 2.0 * tSize, 0.6 * tSize);
            // Mast stump
            ctx.fillStyle = '#aaa';
            ctx.fillRect(-0.35 * tSize, -0.05 * tSize, 0.1 * tSize, 0.1 * tSize);
            // Fallen mast (line across deck)
            ctx.strokeStyle = '#bbb';
            ctx.lineWidth = Math.max(1, tSize * 0.08);
            ctx.beginPath();
            ctx.moveTo(-0.3 * tSize, 0);
            ctx.lineTo( 1.1 * tSize,  0.35 * tSize);
            ctx.stroke();
            ctx.restore();
            ctx.shadowBlur = 0;
            if (isSelected && sbUI) {
                sbUI.style.display = 'block';
                sbUI.style.left = Math.min(600 - 130, Math.max(0, ox + 20)) + 'px';
                sbUI.style.top = Math.min(600 - 60, Math.max(0, oy)) + 'px';
                const angleEl = document.getElementById('m_sb_angle') as HTMLInputElement;
                if (angleEl) angleEl.value = (sb.angle ?? 0).toString();
            }
        } else if ((obj as any).type === 'ornithopter_wreck') {
            const ow = obj as any;
            const ox = (ow.x + 0.5 - state.panX) * tSize;
            const oy = (ow.y + 0.5 - state.panY) * tSize;
            const rad = ((ow.angle ?? 0) * Math.PI) / 180;
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#fa0'; }
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            // Scorch mark
            ctx.fillStyle = '#1a1612';
            ctx.beginPath();
            ctx.ellipse(0.3 * tSize, 0, 0.9 * tSize, 0.5 * tSize, 0, 0, Math.PI * 2);
            ctx.fill();
            // Body
            ctx.fillStyle = '#d0d0d0';
            ctx.fillRect(-1.4 * tSize, -0.2 * tSize, 2.1 * tSize, 0.4 * tSize);
            // Right wing (intact, flat)
            ctx.fillStyle = '#c8c8c8';
            ctx.beginPath();
            ctx.moveTo( 0.2 * tSize, -0.25 * tSize);
            ctx.lineTo(-0.5 * tSize, -0.22 * tSize);
            ctx.lineTo(-0.1 * tSize, -3.0 * tSize);
            ctx.lineTo( 0.1 * tSize, -3.0 * tSize);
            ctx.closePath();
            ctx.fill();
            // Left wing — just a torn root stump
            ctx.fillStyle = '#b8b8b8';
            ctx.beginPath();
            ctx.moveTo( 0.2 * tSize,  0.25 * tSize);
            ctx.lineTo(-0.3 * tSize,  0.22 * tSize);
            ctx.lineTo(-0.1 * tSize,  0.55 * tSize);
            ctx.lineTo( 0.15 * tSize, 0.5 * tSize);
            ctx.closePath();
            ctx.fill();
            // Jagged tear edge on stump
            ctx.strokeStyle = '#888';
            ctx.lineWidth = Math.max(1, tSize * 0.06);
            ctx.beginPath();
            ctx.moveTo(-0.3 * tSize, 0.22 * tSize);
            ctx.lineTo(-0.22 * tSize, 0.38 * tSize);
            ctx.lineTo(-0.1 * tSize, 0.55 * tSize);
            ctx.stroke();
            // Detached wing fragment lying nearby at an angle
            ctx.save();
            ctx.translate(-0.2 * tSize, 1.6 * tSize);
            ctx.rotate(0.4);
            ctx.fillStyle = '#b8b8b8';
            ctx.beginPath();
            ctx.moveTo(  0,             0);
            ctx.lineTo(-0.35 * tSize,  0.08 * tSize);
            ctx.lineTo(-0.1 * tSize,   2.0 * tSize);
            ctx.lineTo( 0.12 * tSize,  1.8 * tSize);
            ctx.closePath();
            ctx.fill();
            ctx.restore();
            // Cockpit — broken glass: outline + radiating cracks
            const cpx = 0.68 * tSize;
            const cpy = 0;
            ctx.strokeStyle = '#5a9db8';
            ctx.lineWidth = Math.max(1, tSize * 0.07);
            ctx.beginPath();
            ctx.ellipse(cpx, cpy, 0.22 * tSize, 0.15 * tSize, 0, 0, Math.PI * 2);
            ctx.stroke();
            ctx.strokeStyle = '#7aadcc';
            ctx.lineWidth = Math.max(1, tSize * 0.04);
            [0.3, 1.1, 1.9, 2.9, 3.8, 4.7, 5.6].forEach(a => {
                ctx.beginPath();
                ctx.moveTo(cpx, cpy);
                ctx.lineTo(cpx + Math.cos(a) * 0.2 * tSize, cpy + Math.sin(a) * 0.13 * tSize);
                ctx.stroke();
            });
            ctx.restore();
            ctx.shadowBlur = 0;
            if (isSelected && owUI) {
                owUI.style.display = 'block';
                owUI.style.left = Math.min(600 - 130, Math.max(0, ox + 20)) + 'px';
                owUI.style.top = Math.min(600 - 60, Math.max(0, oy)) + 'px';
                const angleEl = document.getElementById('m_ow_angle') as HTMLInputElement;
                if (angleEl) angleEl.value = (ow.angle ?? 0).toString();
            }
        } else if ((obj as any).type === 'baywatch_car') {
            const bc = obj as any;
            const ox = (bc.x + 0.5 - state.panX) * tSize;
            const oy = (bc.y + 0.5 - state.panY) * tSize;
            const rad = ((bc.angle ?? 0) * Math.PI) / 180;
            if (isSelected) { ctx.shadowBlur = 8; ctx.shadowColor = '#f44'; }
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            // chassis: -0.85..0.935 × ±0.425 (×0.85 scale)
            ctx.fillStyle = '#cc2200';
            ctx.fillRect(-0.85 * tSize, -0.425 * tSize, 1.785 * tSize, 0.85 * tSize);
            ctx.fillStyle = '#ff4422';
            ctx.fillRect(-0.5 * tSize, -0.6 * tSize, 1.0 * tSize, 0.55 * tSize);
            ctx.restore();
            ctx.shadowBlur = 0;
            if (isSelected && bwcUI) {
                bwcUI.style.display = 'block';
                bwcUI.style.left = Math.min(600 - 140, Math.max(0, ox + 20)) + 'px';
                bwcUI.style.top = Math.min(600 - 60, Math.max(0, oy)) + 'px';
                const el = document.getElementById('m_bwc_angle') as HTMLInputElement;
                if (el) el.value = ((obj as any).angle ?? 0).toString();
            }
        } else if ((obj as any).type === 'baywatch_hq') {
            const bh = obj as any;
            const ox = (bh.x + 0.5 - state.panX) * tSize;
            const oy = (bh.y + 0.5 - state.panY) * tSize;
            if (isSelected) { ctx.shadowBlur = 8; ctx.shadowColor = '#f44'; }
            // main: -2.2..2.64 × ±1.44 (×2.0 scale)
            ctx.fillStyle = '#cc2200';
            ctx.fillRect(ox - 2.2 * tSize, oy - 1.44 * tSize, 4.84 * tSize, 2.88 * tSize);
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(ox - 0.5 * tSize, oy, 1.0 * tSize, 1.44 * tSize);
            ctx.fillStyle = '#dd3300';
            ctx.fillRect(ox - 2.2 * tSize, oy - 0.7 * tSize, 4.84 * tSize, 0.5 * tSize);
            ctx.shadowBlur = 0;
            if (isSelected && bwhUI) {
                bwhUI.style.display = 'block';
                bwhUI.style.left = Math.min(600 - 140, Math.max(0, ox + 20)) + 'px';
                bwhUI.style.top = Math.min(600 - 60, Math.max(0, oy)) + 'px';
            }
        } else if ((obj as any).type === 'baywatch_tower') {
            const bt = obj as any;
            const ox = (bt.x + 0.5 - state.panX) * tSize;
            const oy = (bt.y + 0.5 - state.panY) * tSize;
            if (isSelected) { ctx.shadowBlur = 8; ctx.shadowColor = '#f44'; }
            // base platform: -1.1..2.52 × ±0.9 (×2.0 scale)
            ctx.fillStyle = '#d8d0b8';
            ctx.fillRect(ox - 1.1 * tSize, oy - 0.9 * tSize, 3.62 * tSize, 1.8 * tSize);
            // cabin: -0.6..0.5 × ±0.6
            ctx.fillStyle = '#cc2200';
            ctx.fillRect(ox - 0.6 * tSize, oy - 0.6 * tSize, 1.1 * tSize, 1.2 * tSize);
            ctx.fillStyle = '#e8e8e8';
            ctx.fillRect(ox - 0.5 * tSize, oy - 0.5 * tSize, 0.9 * tSize, 1.0 * tSize);
            ctx.shadowBlur = 0;
            if (isSelected && bwtUI2) {
                bwtUI2.style.display = 'block';
                bwtUI2.style.left = Math.min(600 - 140, Math.max(0, ox + 20)) + 'px';
                bwtUI2.style.top = Math.min(600 - 60, Math.max(0, oy)) + 'px';
            }
        } else if (obj.type === 'concert_stage') {
            ctx.fillStyle = '#7a2aee';
            ctx.fillRect(ox - 2 * tSize, oy - 2.5 * tSize, 4 * tSize, 5 * tSize);
            ctx.fillStyle = '#2a1040';
            ctx.fillRect(ox - 1.5 * tSize, oy - 2 * tSize, 3 * tSize, 4 * tSize);
            ctx.shadowBlur = 0;
            if (isSelected && csUI) {
                csUI.style.display = 'block';
                csUI.style.left = Math.min(600 - 140, Math.max(0, ox + 20)) + 'px';
                csUI.style.top = Math.min(600 - 60, Math.max(0, oy)) + 'px';
            }
        } else if (obj.type === 'festival_tent') {
            const _tentVariantColors: Record<string, string> = { red: '#bb3018', green: '#2a8030' };
            ctx.fillStyle = _tentVariantColors[(obj as any).colorVariant] ?? '#2266cc';
            ctx.beginPath();
            ctx.moveTo(ox, oy - 0.7 * tSize);
            ctx.lineTo(ox - 0.55 * tSize, oy + 0.55 * tSize);
            ctx.lineTo(ox + 0.55 * tSize, oy + 0.55 * tSize);
            ctx.closePath();
            ctx.fill();
            ctx.shadowBlur = 0;
            if (isSelected && ftUI) {
                const colorSel = document.getElementById('m_tent_color') as HTMLSelectElement;
                if (colorSel) colorSel.value = (obj as any).colorVariant ?? '';
                const angEl = document.getElementById('m_tent_angle') as HTMLInputElement;
                if (angEl) angEl.value = String((obj as any).angle ?? 0);
                ftUI.style.display = 'block';
                ftUI.style.left = Math.min(600 - 180, Math.max(0, ox + 20)) + 'px';
                ftUI.style.top = Math.min(600 - 90, Math.max(0, oy)) + 'px';
            }
        } else if (obj.type === 'festival_tent_broken') {
            const _tbVariantColors: Record<string, string> = { red: '#884422', green: '#335533' };
            ctx.fillStyle = _tbVariantColors[(obj as any).colorVariant] ?? '#6688aa';
            ctx.beginPath();
            ctx.moveTo(ox - 0.7 * tSize, oy);
            ctx.lineTo(ox, oy - 0.25 * tSize);
            ctx.lineTo(ox + 0.7 * tSize, oy);
            ctx.lineTo(ox, oy + 0.15 * tSize);
            ctx.closePath();
            ctx.fill();
            ctx.shadowBlur = 0;
            if (isSelected && ftbUI) {
                const colorSel = document.getElementById('m_tent_broken_color') as HTMLSelectElement;
                if (colorSel) colorSel.value = (obj as any).colorVariant ?? '';
                const angEl = document.getElementById('m_tent_broken_angle') as HTMLInputElement;
                if (angEl) angEl.value = String((obj as any).angle ?? 0);
                ftbUI.style.display = 'block';
                ftbUI.style.left = Math.min(600 - 180, Math.max(0, ox + 20)) + 'px';
                ftbUI.style.top = Math.min(600 - 90, Math.max(0, oy)) + 'px';
            }
        } else if (obj.type === 'festival_car') {
            const _carVariantColors: Record<string, string> = {
                red: '#cc2020', blue: '#204499', black: '#333', yellow: '#cc9900',
            };
            ctx.fillStyle = _carVariantColors[(obj as any).colorVariant] ?? '#9aabb5';
            ctx.fillRect(ox - 0.9 * tSize, oy - 0.5 * tSize, 1.8 * tSize, tSize);
            ctx.shadowBlur = 0;
            if (isSelected && fcUI) {
                const colorSel = document.getElementById('m_fcar_color') as HTMLSelectElement;
                if (colorSel) colorSel.value = (obj as any).colorVariant ?? '';
                const angleEl = document.getElementById('m_fcar_angle') as HTMLInputElement;
                if (angleEl) angleEl.value = ((obj as any).angle ?? 0).toString();
                fcUI.style.display = 'block';
                fcUI.style.left = Math.min(600 - 180, Math.max(0, ox + 20)) + 'px';
                fcUI.style.top = Math.min(600 - 90, Math.max(0, oy)) + 'px';
            }
        } else if (obj.type === 'xmas_house_a' || obj.type === 'xmas_house_b') {
            const rad = (((obj as any).angle ?? 0) * Math.PI) / 180;
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#aaddff'; }
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            ctx.fillStyle = obj.type === 'xmas_house_a' ? '#aaddff' : '#88bbee';
            ctx.fillRect(-tSize, -tSize * 1.2, tSize * 2, tSize * 1.2);
            ctx.restore();
            ctx.shadowBlur = 0;
            if (isSelected && xhUI) {
                const typeSel = document.getElementById('m_xmas_house_type') as HTMLSelectElement;
                if (typeSel) typeSel.value = obj.type;
                const angleEl = document.getElementById('m_xmas_house_angle') as HTMLInputElement;
                if (angleEl) angleEl.value = ((obj as any).angle ?? 0).toString();
                xhUI.style.display = 'block';
                xhUI.style.left = Math.min(600 - 170, Math.max(0, ox + 20)) + 'px';
                xhUI.style.top = Math.min(600 - 90, Math.max(0, oy)) + 'px';
            }
        } else if (obj.type === 'xmas_lantern') {
            const rad = (((obj as any).angle ?? 0) * Math.PI) / 180;
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#ffee88'; }
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            ctx.fillStyle = '#ffee88';
            ctx.beginPath();
            ctx.arc(0, -0.4 * tSize, Math.max(4, tSize * 0.3), 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
            ctx.shadowBlur = 0;
            if (isSelected && xlUI) {
                const angleEl = document.getElementById('m_xmas_lantern_angle') as HTMLInputElement;
                if (angleEl) angleEl.value = ((obj as any).angle ?? 0).toString();
                xlUI.style.display = 'block';
                xlUI.style.left = Math.min(600 - 160, Math.max(0, ox + 20)) + 'px';
                xlUI.style.top = Math.min(600 - 80, Math.max(0, oy)) + 'px';
            }
        } else if (obj.type === 'sleigh') {
            const rad = (((obj as any).angle ?? 0) * Math.PI) / 180;
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#ee3300'; }
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            ctx.fillStyle = '#ee3300';
            ctx.fillRect(-tSize * 0.8, -0.3 * tSize, tSize * 1.6, tSize * 0.6);
            ctx.restore();
            ctx.shadowBlur = 0;
            if (isSelected && slUI) {
                const angleEl = document.getElementById('m_sleigh_angle') as HTMLInputElement;
                if (angleEl) angleEl.value = ((obj as any).angle ?? 0).toString();
                slUI.style.display = 'block';
                slUI.style.left = Math.min(600 - 160, Math.max(0, ox + 20)) + 'px';
                slUI.style.top = Math.min(600 - 80, Math.max(0, oy)) + 'px';
            }
        } else if (obj.type === 'reindeer') {
            const rad = (((obj as any).angle ?? 0) * Math.PI) / 180;
            if (isSelected) { ctx.shadowBlur = 10; ctx.shadowColor = '#cc8844'; }
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(rad);
            ctx.fillStyle = '#cc8844';
            ctx.fillRect(-tSize * 0.6, -0.3 * tSize, tSize * 1.2, tSize * 0.6);
            ctx.restore();
            ctx.shadowBlur = 0;
            if (isSelected && rdUI) {
                const angleEl = document.getElementById('m_reindeer_angle') as HTMLInputElement;
                if (angleEl) angleEl.value = ((obj as any).angle ?? 0).toString();
                rdUI.style.display = 'block';
                rdUI.style.left = Math.min(600 - 160, Math.max(0, ox + 20)) + 'px';
                rdUI.style.top = Math.min(600 - 80, Math.max(0, oy)) + 'px';
            }
        } else if ((obj as any).type === 'ring') {
            const r = ((obj as any).radius ?? 2.5) * tSize;
            const angle = (obj as any).angle ?? 0;
            ctx.save();
            if (isSelected) { ctx.shadowBlur = 12; ctx.shadowColor = '#FFD700'; }
            ctx.strokeStyle = isSelected ? '#fff' : '#FFD700';
            ctx.lineWidth = isSelected ? 2.5 : 1.5;
            ctx.beginPath();
            ctx.arc(ox, oy, r, 0, Math.PI * 2);
            ctx.stroke();
            // Dashed line showing the ring's facing direction (normal)
            ctx.strokeStyle = '#FFD700';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.6;
            ctx.setLineDash([3, 3]);
            ctx.beginPath();
            ctx.moveTo(ox - Math.cos(angle) * r, oy - Math.sin(angle) * r);
            ctx.lineTo(ox + Math.cos(angle) * r, oy + Math.sin(angle) * r);
            ctx.stroke();
            ctx.setLineDash([]);
            ctx.globalAlpha = 1;
            ctx.shadowBlur = 0;
            ctx.restore();
        }
    });

    // ── Payloads ───────────────────────────────────────────────────────────────
    const payloads = m.payloads || [];
    payloads.forEach((p, idx) => {
        const px = (p.x + 0.5 - state.panX) * tSize;
        const py = (p.y + 0.5 - state.panY) * tSize;
        const r = Math.max(5, tSize * 0.7);

        const isAttached = !!(p as any).attachTo;
        const isSelectedPayload = state.selectedPayloadIdx === idx;
        if (isSelectedPayload) {
            ctx.shadowBlur = 12;
            ctx.shadowColor = '#fff';
        }
        if (p.type === 'person') {
            ctx.fillStyle = isAttached ? '#88ffcc' : '#ffe033';
            ctx.beginPath();
            ctx.arc(px, py, r * 0.45, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#ffe033';
            ctx.beginPath();
            ctx.arc(px, py - r * 0.65, r * 0.28, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#cc9900';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.arc(px, py, r * 0.45, 0, Math.PI * 2);
            ctx.stroke();
        } else if (p.type === 'rescuer') {
            ctx.fillStyle = isAttached ? '#88ddff' : '#ff6600';
            ctx.beginPath();
            ctx.arc(px, py, r * 0.45, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.arc(px, py - r * 0.65, r * 0.28, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#cc3300';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.arc(px, py, r * 0.45, 0, Math.PI * 2);
            ctx.stroke();
        } else if (p.type === 'reindeer') {
            ctx.fillStyle = isAttached ? '#eebb88' : '#cc8844';
            ctx.fillRect(px - r * 0.7, py - r * 0.3, r * 1.4, r * 0.6);
            ctx.fillStyle = '#cc8844';
            ctx.beginPath();
            ctx.arc(px + r * 0.5, py - r * 0.4, r * 0.25, 0, Math.PI * 2);
            ctx.fill();
        } else if (p.type === 'crate') {
            const s = r * 0.85;
            ctx.fillStyle = isAttached ? '#44ccff' : '#ff8800';
            ctx.fillRect(px - s / 2, py - s / 2, s, s);
            ctx.strokeStyle = '#cc5500';
            ctx.lineWidth = 1.5;
            ctx.strokeRect(px - s / 2, py - s / 2, s, s);
            ctx.beginPath();
            ctx.moveTo(px - s / 2, py - s / 2);
            ctx.lineTo(px + s / 2, py + s / 2);
            ctx.moveTo(px + s / 2, py - s / 2);
            ctx.lineTo(px - s / 2, py + s / 2);
            ctx.strokeStyle = '#cc5500';
            ctx.lineWidth = 1;
            ctx.stroke();
        }
        ctx.shadowBlur = 0;
        // Move-mode indicator
        if (isSelectedPayload && state.moveMode) {
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1.5;
            ctx.setLineDash([3, 3]);
            ctx.beginPath();
            ctx.arc(px, py, r * 1.2, 0, Math.PI * 2);
            ctx.stroke();
            ctx.setLineDash([]);
        }
        if (!(p as any).npcTarget) {
            ctx.fillStyle = '#fff';
            ctx.font = `bold ${Math.max(8, tSize * 0.55)}px monospace`;
            ctx.textAlign = 'center';
            ctx.fillText(String(idx + 1), px, py + r * 1.5);
            ctx.textAlign = 'left';
        }
    });

    // ── Foliage (2D) ───────────────────────────────────────────────────────────
    const foliage = (m as any).foliage || [];
    const treeColors: Record<string, string> = {
        pine: '#1a5a1a', oak: '#2a6a1a', bush: '#3a7a2a', dead: '#6a4a2a',
        beach_umbrella: '#cc2200', beach_umbrella_tilted: '#cc2200',
        beach_lounger: '#d8cc90', beach_cooler: '#3366aa',
        beach_person: '#e8c090', swimmer: '#1a88cc',
    };
    foliage.forEach((f: any) => {
        const fx = (f.x - state.panX) * tSize;
        const fy = (f.y - state.panY) * tSize;
        const r = Math.max(3, tSize * 0.6 * (f.s || 1));
        ctx.fillStyle = treeColors[f.type] || '#1a5a1a';
        ctx.beginPath();
        ctx.arc(fx, fy, r, 0, Math.PI * 2);
        ctx.fill();
        if (f.type === 'dead') {
            ctx.strokeStyle = '#8a6a4a';
            ctx.lineWidth = 1;
            ctx.stroke();
        }
    });

    // ── Particle Emitters ─────────────────────────────────────────────────────
    ((m as any).particleEmitters || []).forEach((e: any) => {
        const ex = (e.x - state.panX) * tSize;
        const ey = (e.y - state.panY) * tSize;
        const r = Math.max(4, tSize * 0.5);
        const isFire = e.type === 'fire';
        // outer glow
        ctx.globalAlpha = 0.35;
        ctx.fillStyle = isFire ? '#ff6600' : '#888888';
        ctx.beginPath();
        ctx.arc(ex, ey, r * 1.8, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
        // core
        ctx.fillStyle = isFire ? '#ff4400' : '#666666';
        ctx.beginPath();
        ctx.arc(ex, ey, r, 0, Math.PI * 2);
        ctx.fill();
        // label
        ctx.fillStyle = '#fff';
        ctx.font = `bold ${Math.max(8, tSize * 0.6)}px monospace`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(isFire ? '🔥' : '💨', ex, ey);
        ctx.textAlign = 'left';
        ctx.textBaseline = 'alphabetic';
    });

    // ── Wind compass ───────────────────────────────────────────────────────────
    const dirRad = (m.windDir * Math.PI) / 180;
    if (state.selectedUI === 'wind') {
        ctx.shadowBlur = 10;
        ctx.shadowColor = COLORS.windActive;
    }
    ctx.fillStyle = COLORS.shadow;
    ctx.beginPath();
    ctx.arc(50, 50, 30, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = state.selectedUI === 'wind' ? COLORS.windActive : COLORS.padStroke;
    ctx.stroke();
    ctx.shadowBlur = 0;
    if (m.windStr > 0) {
        const maxStr    = 10;
        const str01     = Math.min(m.windStr, maxStr) / maxStr;
        const arrowLen  = 8 + Math.sqrt(str01) * 16;  // min 8px at windStr→0, 24px at max
        const tipX = 50 + Math.cos(dirRad) * arrowLen;
        const tipY = 50 + Math.sin(dirRad) * arrowLen;
        ctx.lineWidth = 1.5 + str01 * 2;
        ctx.beginPath();
        ctx.moveTo(50, 50);
        ctx.lineTo(tipX, tipY);
        ctx.stroke();
        // Arrowhead
        const headLen = 5, spread = 0.4;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(tipX, tipY);
        ctx.lineTo(tipX - Math.cos(dirRad - spread) * headLen, tipY - Math.sin(dirRad - spread) * headLen);
        ctx.moveTo(tipX, tipY);
        ctx.lineTo(tipX - Math.cos(dirRad + spread) * headLen, tipY - Math.sin(dirRad + spread) * headLen);
        ctx.stroke();
        // Speed label
        ctx.fillStyle = state.selectedUI === 'wind' ? COLORS.windActive : COLORS.padStroke;
        ctx.font = 'bold 9px monospace';
        ctx.fillText(`${m.windStr.toFixed(1)}`, 84, 54);
    }
    ctx.lineWidth = 1;
    if (state.selectedUI === 'wind' && wUI) wUI.style.display = 'block';
};

// Sync vessel settings from m.objects[idx] into the shared vessel UI panel
const syncVesselUI = (obj: any, kind: 'carrier' | 'boat' | 'submarine') => {
    const prefix = kind === 'carrier' ? 'carrier' : kind === 'submarine' ? 'submarine' : 'boat';
    const pathEl = document.getElementById(`m_${prefix}_path`) as HTMLSelectElement;
    const speedEl = document.getElementById(`m_${prefix}_speed`) as HTMLInputElement;
    const radiusEl = document.getElementById(`m_${prefix}_radius`) as HTMLInputElement;
    const angleEl = document.getElementById(`m_${prefix}_angle`) as HTMLInputElement;
    const nameEl = document.getElementById(`m_${prefix}_name`) as HTMLInputElement;
    const exitEl = document.getElementById(`m_${prefix}_exitWarning`) as HTMLInputElement;
    const radioEl = document.getElementById(`m_${prefix}_radioSilent`) as HTMLInputElement;
    if (pathEl) pathEl.value = obj.path ?? 'static';
    if (speedEl) speedEl.value = (obj.speed ?? 0).toString();
    if (radiusEl) radiusEl.value = (obj.radius ?? 40).toString();
    if (angleEl) angleEl.value = (obj.angle ?? 0).toString();
    if (nameEl) nameEl.value = obj.vesselName ?? '';
    if (exitEl) exitEl.checked = obj.exitWarning ?? false;
    if (radioEl) radioEl.checked = !(obj.radioSilent ?? false);
    if (kind === 'boat') {
        const radioRow = document.getElementById('m_boat_radioSilent_row');
        if (radioRow) radioRow.style.display = obj.type === 'frigate' ? '' : 'none';
    }
};


